#include "gateway_debug_page.h"

const char GATEWAY_DEBUG_PAGE[] =
"<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='color-scheme' content='dark'><title>AUBOT | Chẩn đoán</title><link rel='stylesheet' href='/ui.css'><style>"
".diag{display:grid;grid-template-columns:minmax(280px,.7fr) minmax(0,1.3fr);gap:14px}.rows{border-top:1px solid var(--line2)}.row{display:flex;align-items:center;justify-content:space-between;gap:15px;min-height:42px;border-bottom:1px solid var(--line2)}.row span{color:var(--muted)}.row b{font-variant-numeric:tabular-nums;text-align:right}.id-wrap{overflow-x:auto}.id-grid{display:grid;grid-template-columns:48px repeat(8,minmax(44px,1fr));gap:7px;min-width:490px}.group-label,.laser-cell{position:relative;min-height:52px;border:1px solid var(--line2);border-radius:9px;background:var(--glass2);color:var(--muted)}.group-label{display:grid;place-items:center;font-size:10px;font-weight:800}.laser-cell{cursor:pointer;font-weight:800}.laser-cell:before{content:'';position:absolute;right:6px;top:6px;width:7px;height:7px;border-radius:50%;background:#526079}.laser-cell.online{border-color:rgba(52,211,153,.45);background:rgba(20,53,48,.75);color:#bbf7d0}.laser-cell.online:before{background:var(--success)}.laser-cell.warn{border-color:rgba(251,191,36,.55);background:rgba(64,47,20,.8);color:#fde68a}.laser-cell.warn:before{background:var(--warning)}.laser-cell.selected{outline:3px solid rgba(57,205,248,.45);outline-offset:1px}.node-empty{display:grid;place-items:center;min-height:230px;color:var(--muted);text-align:center}.node-data{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}.config-box{margin-top:14px;padding-top:14px;border-top:1px solid var(--line2)}.advanced-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.metric{padding:10px;border:1px solid var(--line2);border-radius:9px;background:var(--glass2)}.metric small{display:block;color:var(--muted);font-size:10px}.metric b{display:block;margin-top:3px;font-size:13px;overflow-wrap:anywhere}.config-actions,.card-tools{display:flex;align-items:center;justify-content:space-between;gap:10px}.config-actions{justify-content:flex-end;margin-top:11px}.matrix-preview{display:grid;grid-template-columns:repeat(8,20px);gap:3px;width:max-content;margin-top:10px}.matrix-preview i{width:20px;height:20px;border:1px solid var(--line2);border-radius:4px;background:#0b1423}.matrix-preview i.on{border-color:rgba(52,211,153,.55);background:rgba(52,211,153,.22)}@media(max-width:900px){.diag{grid-template-columns:1fr}}@media(max-width:540px){.node-data,.advanced-grid{grid-template-columns:1fr}.config-actions{align-items:stretch;flex-direction:column}.config-actions .btn{width:100%}}</style></head><body data-page='tech'><div class='shell'>"
"<header class='hero'><div class='brand'><img class='logo' src='/logo.png' alt='AUBOT'><div><div class='eyebrow'>AUBOT · WAREHOUSE GATEWAY</div><h1>Chẩn đoán hệ thống</h1><p>CAN và cảm biến Laser</p></div></div><div class='header-status'><div data-app-user></div><div class='status-chip' id='canChip'><i></i><small>CAN</small><b>Đang đọc</b></div><div class='status-chip' id='laserChip'><i></i><small>Laser</small><b>Đang đọc</b></div><div class='status-chip' data-network-chip><i></i><small>Mạng</small><b data-network>Đang đọc</b></div><div class='status-chip' data-mqtt-chip><i></i><small>MQTT</small><b data-mqtt>Đang đọc</b></div></div></header><nav class='nav' data-app-nav aria-label='Điều hướng chính'><a href='/'>TỔNG QUAN</a></nav>"
"<main class='diag'><section class='card'><header class='card-head'><span class='step'>01</span><h2>Tổng quan</h2></header><div class='rows'><div class='row'><span>Trạng thái CAN</span><b id='canState'>--</b></div><div class='row'><span>Laser online</span><b id='nodeCount'>0</b></div><div class='row'><span>Khung RX</span><b id='rxFrames'>0</b></div><div class='row'><span>TX thất bại</span><b id='txFail'>0</b></div><div class='row'><span>RX bỏ qua / tràn</span><b id='rxDrop'>0 / 0</b></div><div class='row'><span>Lỗi bus</span><b id='busErrors'>0</b></div></div></section>"
"<section class='card'><header class='card-head'><span class='step'>02</span><div><h2>Laser ID</h2><p class='hint'>Chọn một ô sáng để xem chi tiết</p></div></header><div class='id-wrap'><div id='idGrid' class='id-grid' role='grid' aria-label='Ma trận 64 Laser ID'></div></div></section>"
"<section class='card'><header class='card-head'><span class='step'>03</span><h2>Chi tiết Laser</h2></header><div id='nodeEmpty' class='node-empty'>Chọn một Laser để xem chi tiết</div><div id='nodeDetail' class='hidden'><div id='nodeRows' class='node-data rows'></div><div class='config-box'><div class='card-tools'><div><b>Cấu hình nhóm Laser</b><p class='hint'>Áp dụng cho nhóm phần cứng chứa Laser đã chọn.</p></div><span id='groupBadge' class='badge'>--</span></div><div class='fields'><label class='field'><span>Khoảng cách (mm)</span><input id='distance' type='number' min='0' max='1200'></label><label class='field'><span>Khẩn cấp (mm)</span><input id='emergency' type='number' min='0' max='1200'></label><label class='switch-line full'><span>Bật phát hiện vật cản</span><input id='enabled' type='checkbox'></label></div><details style='margin-top:11px'><summary>Vùng quan sát 8×8</summary><div class='details-body'><div class='fields'><label class='field'><span>Mặt nạ hàng</span><input id='highRow' type='number' min='0' max='255'></label><label class='field'><span>Mặt nạ cột</span><input id='lowCol' type='number' min='0' max='255'></label></div><div id='matrix' class='matrix-preview' aria-label='Xem trước vùng quan sát'></div><p class='hint'>Ô sáng là vùng đang được theo dõi.</p></div></details><div class='config-actions'><div id='configFeedback' class='message' role='status'></div><button id='applyConfig' class='btn primary' type='button'>Gửi cấu hình</button></div></div></div></section>"
"<section class='card'><header class='card-head'><span class='step'>04</span><h2>CAN nâng cao</h2></header><details><summary>Bộ đếm và khung CAN gần nhất</summary><div class='details-body'><div id='advancedGrid' class='advanced-grid'></div></div></details></section></main><footer class='toolbar' style='margin-top:14px'><span id='updated' class='summary-line'>Đang kết nối…</span><button id='toggle' class='btn ghost' type='button'>Tạm dừng</button></footer></div>"
"<dialog id='confirmDialog'><header class='dialog-head'><h2>Xác nhận cấu hình nhóm</h2><button id='cancelTop' class='btn ghost' type='button'>Đóng</button></header><div class='dialog-body'><p id='confirmText'>Kiểm tra thông số trước khi gửi.</p><div id='confirmRows' class='rows'></div><p class='message warning-text'>Laser trong nhóm có thể khởi động lại để nhận cấu hình.</p><div class='dialog-actions'><button id='cancel' class='btn ghost' type='button'>Hủy</button><button id='confirm' class='btn primary' type='button'>Xác nhận gửi</button></div></div></dialog>"
"<script src='/ui.js'></script><script>const $=x=>document.getElementById(x),fmt=x=>Number(x||0).toLocaleString('vi-VN');let nodes=[],selected=null,paused=false,timer,pending=null;const canVi=s=>({ACTIVE:'HOẠT ĐỘNG',WARNING:'CẢNH BÁO',PASSIVE:'THỤ ĐỘNG','BUS-OFF':'MẤT MẠNG',STOPPED:'ĐÃ DỪNG'}[s]||s),cfgVi=s=>({UNMANAGED:'Chưa quản lý',PENDING:'Đang chờ',SENT_UNVERIFIED:'Đã gửi',VERIFIED:'Đã xác nhận',MISMATCH:'Chưa khớp',FAILED:'Gửi lỗi'}[s]||s),obVi=s=>({CLEAR:'Không có hàng',NORMAL:'Có hàng',EMERGENCY:'Có hàng'}[s]||'Chưa xác định');function grid(){let h='';for(let r=0;r<8;r++){h+=`<div class='group-label'>N${r+1}</div>`;for(let c=0;c<8;c++){const id=r*8+c+1,n=nodes.find(x=>x.id===id),warn=n&&n.obstacle_valid&&n.obstacle!=='CLEAR',cls=n&&n.alive?(warn?'warn':'online'):'',sel=id===selected?'selected':'';h+=`<button class='laser-cell ${cls} ${sel}' type='button' data-id='${id}' ${n?'':'disabled'} aria-label='Laser ${id} ${n&&n.alive?'online':'offline'}'>${id}</button>`}}$('idGrid').innerHTML=h;$('idGrid').querySelectorAll('[data-id]:not(:disabled)').forEach(b=>b.onclick=()=>select(Number(b.dataset.id)))}function row(k,v){return `<div class='row'><span>${k}</span><b>${v}</b></div>`}function select(id){selected=id;const n=nodes.find(x=>x.id===id);if(!n)return;$('nodeEmpty').classList.add('hidden');$('nodeDetail').classList.remove('hidden');$('nodeRows').innerHTML=row('Laser ID',n.id)+row('Nhóm',n.group)+row('Kết nối',n.alive?'Online':'Mất phản hồi')+row('Nhận gần nhất',fmt(n.last_seen_ago_ms)+' ms')+row('Trạng thái dữ liệu',n.status_valid?'Hợp lệ':'Chưa hợp lệ')+row('Kho hàng',n.obstacle_valid?obVi(n.obstacle):'Chưa xác định')+row('Khoảng cách',fmt(n.distance_mm)+' mm')+row('Khẩn cấp',fmt(n.emergency_mm)+' mm')+row('Cấu hình',cfgVi(n.config_state));$('groupBadge').textContent='NHÓM '+n.group;$('distance').value=n.distance_mm;$('emergency').value=n.emergency_mm;$('lowCol').value=n.low_col;$('highRow').value=n.high_row;$('enabled').checked=n.enabled;$('configFeedback').textContent='';matrix();grid()}function matrix(){const rows=Number($('highRow').value)||0,cols=Number($('lowCol').value)||0;let h='';for(let r=0;r<8;r++)for(let c=7;c>=0;c--)h+=`<i class='${!(rows&(1<<r))&&!(cols&(1<<c))?'on':''}'></i>`;$('matrix').innerHTML=h}function metric(k,v){return `<div class='metric'><small>${k}</small><b>${v}</b></div>`}"
"function render(d){nodes=d.nodes||[];const c=d.can,l=d.laser,online=nodes.filter(n=>n.alive).length;$('canState').textContent=canVi(c.state);$('nodeCount').textContent=online;$('rxFrames').textContent=fmt(l.rx_frames);$('txFail').textContent=fmt(c.tx_fail);$('rxDrop').textContent=fmt(c.rx_rejected)+' / '+fmt(c.rx_dropped);$('busErrors').textContent=fmt(c.bus_error);$('canChip').className='status-chip '+(c.state==='ACTIVE'?'ok':c.state==='WARNING'?'warn':'bad');$('canChip').querySelector('b').textContent=canVi(c.state);$('laserChip').className='status-chip '+(online?'ok':'bad');$('laserChip').querySelector('b').textContent=online+' online';$('advancedGrid').innerHTML=metric('TX thành công',fmt(c.tx_ok))+metric('TX thất bại',fmt(c.tx_fail))+metric('TX error',fmt(c.tx_error))+metric('RX error',fmt(c.rx_error))+metric('RX loại bỏ',fmt(c.rx_rejected))+metric('RX tràn',fmt(c.rx_dropped))+metric('Sự kiện lỗi',fmt(c.error_events))+metric('Mất phân xử',fmt(c.arbitration_lost))+metric('Lỗi bit',fmt(c.bit_errors))+metric('Lỗi định dạng',fmt(c.form_errors))+metric('Lỗi nhồi bit',fmt(c.stuff_errors))+metric('Lỗi ACK',fmt(c.ack_errors))+metric('ID gần nhất',l.detected?'0x'+Number(l.last_id).toString(16).toUpperCase().padStart(3,'0'):'--')+metric('DLC gần nhất',l.detected?l.last_dlc:'--')+metric('Loại khung',l.detected?(l.remote?'REMOTE':'DATA'):'--');$('updated').textContent='Cập nhật '+new Date().toLocaleTimeString('vi-VN');if(selected&&!nodes.some(n=>n.id===selected)){selected=null;$('nodeEmpty').classList.remove('hidden');$('nodeDetail').classList.add('hidden')}if(selected)select(selected);else grid()}async function hero(){try{const x=await(await fetch('/api/ui/status',{cache:'no-store'})).json();document.querySelector('[data-network]').textContent=x.network?x.network_name:'Chưa kết nối';document.querySelector('[data-mqtt]').textContent=x.mqtt?'Đã kết nối':'Chưa kết nối';document.querySelector('[data-network-chip]').classList.toggle('ok',x.network);document.querySelector('[data-mqtt-chip]').classList.toggle('ok',x.mqtt)}catch(e){}}async function poll(){if(paused)return;try{const r=await fetch('/api/debug/status',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);render(await r.json());hero()}catch(e){$('updated').textContent='Không lấy được dữ liệu'}timer=setTimeout(poll,750)}"
"function prepare(){const n=nodes.find(x=>x.id===selected),distance=Number($('distance').value),emergency=Number($('emergency').value);if(!n)return;if(emergency>distance){$('configFeedback').textContent='Khoảng cách khẩn cấp phải nhỏ hơn hoặc bằng khoảng cách.';$('configFeedback').className='message bad';return}pending={laser_id:n.id,distance_mm:distance,emergency_mm:emergency,low_col:$('lowCol').value,high_row:$('highRow').value,enabled:$('enabled').checked?1:0};$('confirmText').textContent='Cấu hình sẽ áp dụng cho toàn bộ nhóm '+n.group+'.';$('confirmRows').innerHTML=row('Laser tham chiếu','ID '+n.id)+row('Nhóm',n.group)+row('Khoảng cách',distance+' mm')+row('Khẩn cấp',emergency+' mm');$('confirmDialog').showModal()}async function send(){if(!pending)return;const p=pending;pending=null;$('confirmDialog').close();$('applyConfig').disabled=true;$('configFeedback').textContent='Đang gửi cấu hình qua CAN…';try{const r=await fetch('/api/laser/config',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(p)});if(!r.ok)throw Error(await r.text());$('configFeedback').textContent='Đã gửi yêu cầu cấu hình.';$('configFeedback').className='message ok'}catch(e){$('configFeedback').textContent='Gửi thất bại: '+e.message;$('configFeedback').className='message bad'}finally{$('applyConfig').disabled=false}}['highRow','lowCol'].forEach(x=>$(x).oninput=matrix);$('applyConfig').onclick=prepare;$('cancel').onclick=$('cancelTop').onclick=()=>{$('confirmDialog').close();pending=null};$('confirm').onclick=send;$('toggle').onclick=()=>{paused=!paused;$('toggle').textContent=paused?'Tiếp tục':'Tạm dừng';if(paused){clearTimeout(timer);$('updated').textContent='Đã tạm dừng'}else poll()};grid();poll()</script></body></html>";
